package io.atlas.modules.market;
import io.atlas.modules.market.model.MarketSpriteRules;import java.util.*;
public final class MarketSpriteRulesTest {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 public static void main(String[] args)throws Exception{List<MarketSpriteRules.Sprite> sprites;try(var input=MarketSpriteRulesTest.class.getResourceAsStream("/atlas-gts/e19-sprites.json")){sprites=List.of(new com.google.gson.Gson().fromJson(new java.io.InputStreamReader(input),MarketSpriteRules.Sprite[].class));}
  var base=MarketSpriteRules.select(sprites,150,"Mewtwo",List.of(),"GENDERLESS","Normal",false).orElseThrow();check(base.path().equals("regular/0150_mewtwo.png"),"exact minimap base sprite");var shiny=MarketSpriteRules.select(sprites,150,"Mewtwo",List.of("shiny"),"GENDERLESS","Normal",true).orElseThrow();check(shiny.path().equals("shiny/0150_mewtwo_shiny.png")&&shiny.id()!=base.id(),"distinct shiny sprite");var female=MarketSpriteRules.select(sprites,3,"Venusaur",List.of("shiny","female"),"FEMALE","Normal",true).orElseThrow();check(female.path().contains("female_shiny"),"gender and shiny variant");var mega=MarketSpriteRules.select(sprites,6,"Charizard",List.of("mega-x"),"MALE","Mega X",false).orElseThrow();check(mega.path().contains("megax"),"form aspect normalized");check(MarketSpriteRules.select(sprites,487,"Giratina",List.of("origin"),"GENDERLESS","Origin",false).orElseThrow().path().contains("origin"),"default-less species form");check(MarketSpriteRules.select(sprites,718,"Zygarde",List.of("50-percent"),"GENDERLESS","50%",false).orElseThrow().path().contains("_50"),"numeric form");check(MarketSpriteRules.select(sprites,9999,"Unknown",List.of(),"MALE","Normal",false).isEmpty(),"unsupported uses native fallback");check(MarketSpriteRules.normalize("Flabébé").equals("flabebe")&&MarketSpriteRules.normalize("Gmax").equals("gigantamax"),"accented names and Gigantamax alias");check(new HashSet<>(sprites.stream().map(MarketSpriteRules.Sprite::id).toList()).size()==sprites.size(),"unique model ids");System.out.println("MarketSpriteRulesTest PASS: original E19 sprites, shiny/gender/forms, numeric forms, unique IDs and unsupported fallback");}
}
